function renderGlobalSearch(){const input=$('#global-search-input'),host=$('#global-search-results'),query=input.value.trim();if(!query){clearGlobalSearch();return}const rows=globalSearchRows(query);if(!rows.length){host.replaceChildren(Object.assign(document.createElement('p'),{className:'global-search-empty',textContent:'没有找到匹配资料'}));return}host.replaceChildren(...rows.map(x=>{const button=document.createElement('button');button.type='button';button.className='global-search-result';button.setAttribute('aria-label',`${names[x.type]} ${itemName(x)}，${globalGroupName(x)}分组`);const title=document.createElement('b');title.textContent=itemName(x);const meta=document.createElement('span');meta.textContent=`${names[x.type]} · ${globalGroupName(x)}`;button.append(title,meta);button.onclick=()=>openGlobalResult(x);return button}))}
