const TRASH_RETENTION_MS=30*24*60*60*1000;
async function cleanupExpiredTrash(key=vaultKey,generation=vaultGeneration){const valid=()=>vaultSessionValid(key,generation);if(!valid())return false;const cutoff=Date.now()-TRASH_RETENTION_MS,expired=trashRows().filter(x=>x.deletedAt<=cutoff);let changed=false,failed=false;for(const x of expired){try{const deleted=await permanentlyDelete(x,key,generation);if(!valid())return false;if(deleted)changed=true}catch{if(!valid())return false;failed=true}}if(!valid())return false;if(changed)markVaultUpdated();if(failed)toast('部分过期资料清理失败，已保留并将在下次解锁时重试');return true}
let trashDeleteTarget=null;
function trashParentNote(x){return resolveTrashParentNote(x,items)}
function linkedTrashAttachments(x){return resolveLinkedTrashAttachments(x,attachments,items)}
async function permanentlyDelete(x,key=vaultKey,generation=vaultGeneration){const valid=()=>vaultSessionValid(key,generation);if(!valid()||(x.type==='attachment'?!attachments.includes(x):!items.includes(x)))return false;if(x.type==='attachment'){await api('/api/attachments/'+x.id,{method:'DELETE'});if(!valid())return false;attachments=attachments.filter(v=>v!==x);revokeUrls()}else{const linked=linkedTrashAttachments(x),detached=[];try{for(const file of linked){const candidate={...file};delete candidate.trashOwnerId;await putGroupedValue(candidate);if(!valid())return false;detached.push(file)}await api('/api/entries/'+x.id,{method:'DELETE'});if(!valid())return false}catch(err){if(!valid())return false;let compensationFailed=false;for(const file of detached.reverse())try{await putGroupedValue(file);if(!valid())return false}catch{if(!valid())return false;compensationFailed=true}if(compensationFailed)try{if(await load())render(false)}catch{}if(!valid())return false;throw Error(compensationFailed?'彻底删除失败且附件回滚未完成，已重新同步，请重试':err.message)}items=items.filter(v=>v!==x);for(const file of linked)delete file.trashOwnerId;let attachmentFailure=false;for(const file of linked)try{if(!await permanentlyDelete(file,key,generation)&&!valid())return false}catch{if(!valid())return false;attachmentFailure=true}if(attachmentFailure){const err=Error('关联附件未全部删除，已保留为独立回收站项目，可单独重试');err.partial=true;throw err}}if(!valid())return false;recents=recents.filter(r=>!(r.type===x.type&&r.id===x.id));return true}
async function restoreTrashItem(x){const linked=linkedTrashAttachments(x),batch=[...linked,x],restored=[],fallback=[];try{for(const item of batch){const candidate={...item};delete candidate.deletedAt;delete candidate.trashOwnerId;if(candidate.groupId&&!groups[item.type].some(g=>g.id===candidate.groupId)){delete candidate.groupId;fallback.push(item)}await putGroupedValue(candidate);restored.push({item,candidate})}for(const {item,candidate} of restored){delete item.deletedAt;delete item.trashOwnerId;if(!candidate.groupId)delete item.groupId}return fallback.length}catch(err){let compensationFailed=false;for(const {item} of restored.reverse())try{await putGroupedValue(item)}catch{compensationFailed=true}if(compensationFailed)try{await load();render(false)}catch{}throw Error(compensationFailed?'恢复失败且回滚未完成，已重新同步，请重试':err.message)}}
function requestPermanentDelete(x){trashDeleteTarget=x;$('#trash-delete-name').textContent=itemName(x);$('#trash-delete-error').textContent='';openDialog($('#trash-delete-dialog'),$('#trash-delete-title'))}
$('#trash-delete-form').onsubmit=async e=>{e.preventDefault();const x=trashDeleteTarget,button=e.currentTarget.querySelector('[type=submit]'),key=vaultKey,generation=vaultGeneration,valid=()=>vaultSessionValid(key,generation);if(!x||!valid())return;busy(button,true,'删除中…');try{if(!await permanentlyDelete(x,key,generation)||!valid())return;$('#trash-delete-dialog').close();renderTrash();render(false);markVaultUpdated();toast('已彻底删除')}catch(err){if(!valid())return;if(err.partial){$('#trash-delete-dialog').close();trashDeleteTarget=null;renderTrash();render(false);markVaultUpdated()}const message=`彻底删除失败：${err.message}`;$('#trash-delete-error').textContent=message;toast(message)}finally{if(valid())busy(button,false)}};
$('#trash-empty').onclick=()=>{const rows=trashRows();if(!rows.length)return;$('#trash-empty-count').textContent=String(rows.length);$('#trash-empty-error').textContent='';openDialog($('#trash-empty-dialog'),$('#trash-empty-title'))};
$('#trash-empty-form').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('[type=submit]'),rows=trashRows(),key=vaultKey,generation=vaultGeneration,valid=()=>vaultSessionValid(key,generation);if(!valid())return;busy(button,true,'清空中…');try{for(const x of rows)if(!await permanentlyDelete(x,key,generation)||!valid())return;$('#trash-empty-dialog').close();renderTrash();render(false);markVaultUpdated();toast('回收站已清空')}catch(err){if(!valid())return;const message=`清空失败：${err.message}`;$('#trash-empty-error').textContent=message;renderTrash();toast(message)}finally{if(valid())busy(button,false)}};
function trashRows(){return[...items.filter(x=>GROUP_TYPES.includes(x.type)&&x.deletedAt),...attachments.filter(x=>x.deletedAt)].sort((a,b)=>b.deletedAt-a.deletedAt)}
