$('#trash-open').onclick=()=>{closeHeaderMenu();renderTrash();openDialog($('#trash-dialog'),$('#trash-title'))};
$('#trash-dialog').addEventListener('close',()=>$('#trash-list').replaceChildren(Object.assign(document.createElement('p'),{className:'trash-empty',textContent:'回收站为空'})));

