async function recordRecent(x){if(!x||!x.id||!x.type||!GROUP_TYPES.includes(x.type))return;const next=normalizeRecents([{type:x.type,id:x.id,at:Date.now()},...recents.filter(r=>!(r.type===x.type&&r.id===x.id))]);if(!next)return;recents=next;if(type===x.type)render(false);try{const encrypted=await encryptItem(vaultKey,recents);await api('/api/entries/'+RECENTS_ID,{method:'PUT',body:JSON.stringify({id:RECENTS_ID,type:'settings',version:1,...encrypted})})}catch{}}
