$('#group-delete-form').onsubmit=async e=>{e.preventDefault();const g=groupTarget,affected=(type==='attachment'?attachments:items).filter(x=>x.type===type&&x.groupId===g.id),succeeded=[],oldGroups=groups,oldActive=activeGroups[type];try{for(const x of affected){await putGroupedValue(x,true);succeeded.push(x)}groups={...groups,[type]:groups[type].filter(x=>x.id!==g.id)};if(activeGroups[type]===g.id)activeGroups[type]=undefined;await persistGroups();for(const x of affected)delete x.groupId;$('#group-delete').close();$('#groups-dialog').close();render();toast('分组已删除，资料已移至默认')}catch(err){groups=oldGroups;activeGroups[type]=oldActive;let compensationFailed=false;for(const x of succeeded.reverse()){try{await putGroupedValue(x)}catch{compensationFailed=true}}if(compensationFailed){try{await load()}catch{}renderGroups();render();toast('删除分组失败且回滚未完成，请刷新后重试')}else{renderGroups();render();toast(`删除分组失败：${err.message}`)}}};
function renderGroupOrder(){const tabs=$$('[data-order-type]');for(const tab of tabs){const selected=tab.dataset.orderType===orderType;tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1}const list=$('#group-order-list'),rows=groups[orderType];if(!rows.length){const empty=document.createElement('p');empty.className='order-empty';empty.textContent='还没有自定义分组';list.replaceChildren(empty);return}list.replaceChildren(...rows.map((g,index)=>{const row=document.createElement('div');row.className='group-order-row';const name=document.createElement('span');name.dataset.orderName='';name.textContent=g.name;const actions=document.createElement('div');actions.className='group-order-actions';const up=actionButton('↑',()=>moveGroup(index,-1)),down=actionButton('↓',()=>moveGroup(index,1));up.setAttribute('aria-label',`上移 ${g.name}`);down.setAttribute('aria-label',`下移 ${g.name}`);up.disabled=index===0;down.disabled=index===rows.length-1;actions.append(up,down);row.append(name,actions);return row}))}
