let pinOrderType='account';function pinnedRows(t){return pinnedFirst((t==='attachment'?attachments:items.filter(x=>x.type===t)).filter(x=>!x.deletedAt&&x.pinned))}function renderPinOrder(){const tabs=$$('[data-pin-order-type]');for(const tab of tabs){const selected=tab.dataset.pinOrderType===pinOrderType;tab.setAttribute('aria-selected',String(selected));tab.tabIndex=selected?0:-1}const list=$('#pin-order-list'),rows=pinnedRows(pinOrderType);if(!rows.length){const empty=document.createElement('p');empty.className='order-empty';empty.textContent='还没有置顶资料';list.replaceChildren(empty);return}list.replaceChildren(...rows.map((x,index)=>{const row=document.createElement('div');row.className='group-order-row';const name=document.createElement('span');name.dataset.pinOrderName='';name.textContent=itemName(x);const actions=document.createElement('div');actions.className='group-order-actions';const up=actionButton('↑',()=>movePinned(index,-1)),down=actionButton('↓',()=>movePinned(index,1));up.setAttribute('aria-label',`上移 ${itemName(x)}`);down.setAttribute('aria-label',`下移 ${itemName(x)}`);up.disabled=index===0;down.disabled=index===rows.length-1;actions.append(up,down);row.append(name,actions);return row}))}async function movePinned(index,offset){const rows=pinnedRows(pinOrderType),target=index+offset;if(target<0||target>=rows.length)return;[rows[index],rows[target]]=[rows[target],rows[index]];const previous=rows.map(x=>x.pinRank),saved=[];rows.forEach((x,i)=>{x.pinRank=i});renderPinOrder();try{for(const x of rows){await putGroupedValue(x);saved.push(x)}render(false);toast('置顶顺序已保存')}catch(err){rows.forEach((x,i)=>{if(Number.isSafeInteger(previous[i]))x.pinRank=previous[i];else delete x.pinRank});for(const x of saved.reverse())try{await putGroupedValue(x)}catch{}renderPinOrder();render(false);toast(`保存置顶顺序失败：${err.message}`)}}$$('[data-pin-order-type]').forEach(tab=>tab.onclick=()=>{pinOrderType=tab.dataset.pinOrderType;renderPinOrder();tab.focus()});$('#pin-order').onclick