$('#menu').onclick=()=>{closeItemMenu();const p=$('#menu-panel'),open=p.hidden;p.hidden=!open;$('#menu').setAttribute('aria-expanded',String(open));if(open)p.querySelector('button').focus()};
function category(file){return file.type.startsWith('image/')?'image':file.type.startsWith('video/')?'video':'other'}
function validName(name){return name&&name.length<=255&&!/[\p{Cc}\p{Cf}]/u.test(name)}
async function uploadAttachment(file,noteId,groupId,sessionKey=vaultKey,sessionGeneration=vaultGeneration){const valid=()=>vaultSessionValid(sessionKey,sessionGeneration);if(!valid())throw Error('密码库已锁定');const limits={image:10*1024*1024,video:100*1024*1024,other:25*1024*1024},kind=category(file);if(!validName(file.name)||file.size>limits[kind])throw Error('文件名称或大小不符合限制');const id=uuid(),buffer=await file.arrayBuffer();if(!valid())throw Error('密码库已锁定');const encrypted=await encryptAttachment(sessionKey,id,buffer);if(!valid())throw Error('密码库已锁定');const metadata={name:file.name,mime:file.type||'application/octet-stream',size:file.size,category:kind,contentIv:encrypted.iv,...(noteId?{noteId}:{}),...(groupId?{groupId}:{})},envelope={version:1,...await encryptItem(sessionKey,metadata)};if(!valid())throw Error('密码库已锁定');const response=await fetch('/api/attachments/'+id,{method:'POST',headers:{'content-type':'application/octet-stream','x-csrf-token':csrf,'x-attachment-metadata':JSON.stringify(envelope)},body:encrypted.ciphertext});if(!valid())throw Error('密码库已锁定');if(!response.ok){let x={};try{x=await response.json()}catch{}throw Error(errorMessage(x.error))}const value={id,...metadata,type:'attachment',createdAt:(await response.clone().json()).createdAt};if(!valid())throw Error('密码库已锁定');attachments.unshift(value);markVaultUpdated();return value}
