function isPdfAttachment(x){const mime=(x.mime||'').toLowerCase(),name=(x.name||'').toLowerCase();return mime==='application/pdf'||mime.endsWith('/pdf')||name.endsWith('.pdf')}
function isTextAttachment(x){const mime=(x.mime||'').toLowerCase(),name=(x.name||'').toLowerCase();if(mime.startsWith('text/'))return true;if(['application/json','application/xml','application/javascript','application/x-javascript','application/sql','application/x-sh','application/x-yaml','application/yaml'].includes(mime))return true;return /\.(txt|md|markdown|json|csv|log|xml|yaml|yml|js|mjs|cjs|ts|tsx|jsx|css|html|htm|svg|py|go|rs|java|c|h|cpp|hpp|sh|bash|zsh|ini|conf|cfg|env|toml)$/i.test(name)}
