let idleTimer=null,lastActivityAt=0;const IDLE_LOCK_CHOICES=[{ms:60000,label:'1 分钟'},{ms:300000,label:'5 分钟'},{ms:900000,label:'15 分钟'},{ms:1800000,label:'30 分钟'},{ms:0,label:'从不'}];
